<template>
  <div class="app-container aps-orders">
    <el-alert v-if="pageError" :title="pageError" type="error" :closable="false"/><el-input v-model="search" placeholder="按订单号或客户筛选" clearable/><el-alert title="一个订单可包含多个独立产品行；跨产品关系只来自显式依赖/组件输入，不按页面顺序自动串行。任务展开使用稳定 ID，重复执行只回读原网络。" type="info" :closable="false" />
    <el-card class="section-card">
      <template #header><div class="head"><span>生产订单</span><div><el-button v-hasPermi="['aps:order:add']" @click="openOrder(false)">新增订单</el-button><el-button type="primary" v-hasPermi="['aps:order:import']" @click="openOrder(true)">幂等导入</el-button></div></div></template>
      <el-table :data="visibleOrders" highlight-current-row @current-change="selectOrder">
        <el-table-column prop="orderNo" label="订单号" min-width="150" /><el-table-column prop="sourceSystem" label="来源" width="100" /><el-table-column prop="externalId" label="外部 ID" min-width="130" /><el-table-column prop="priority" label="优先级" width="90" /><el-table-column label="产品行" width="80"><template #default="s">{{ s.row.lines.length }}</template></el-table-column><el-table-column prop="status" label="状态" width="110" />
        <el-table-column label="操作" width="320"><template #default="s"><el-button v-if="s.row.status==='DRAFT'" v-hasPermi="['aps:order:edit']" link @click.stop="editOrder(s.row)">编辑草稿</el-button><el-button v-hasPermi="['aps:order:edit']" :disabled="saving" link @click.stop="expand(s.row)">展开任务</el-button><el-button link v-hasPermi="['aps:order:release']" @click.stop="release(s.row)" :disabled="saving || s.row.status!=='DRAFT'">结构释放</el-button><a :href="`/aps/readiness?orderId=${s.row.id}`">查看就绪</a></template></el-table-column>
      </el-table>
    </el-card>

    <el-card v-if="selected" class="section-card">
      <template #header><div class="head"><span>{{ selected.orderNo }} · 冻结产品行</span><el-button :disabled="!!expansion?.tasks.length" @click="openMigration">路线迁移差异</el-button></div></template>
      <el-table :data="selected.lines"><el-table-column prop="lineNo" label="行" width="60" /><el-table-column label="产品"><template #default="s">{{ itemName(s.row.itemId) }}</template></el-table-column><el-table-column label="路线版本"><template #default="s">{{ routeName(s.row.routeVersionId) }}</template></el-table-column><el-table-column prop="demandQty" label="数量" width="100" /><el-table-column prop="uomCode" label="单位" width="80" /><el-table-column label="显式跨产品依赖" width="150"><template #default="s">{{ s.row.dependencies.length }}</template></el-table-column></el-table>
    </el-card>

    <el-card v-if="expansion" class="section-card">
      <template #header><div class="head"><span>冻结任务网络</span><el-tag :type="expansion.reused?'info':'success'">{{ expansion.reused ? '复用原展开' : '首次展开' }}</el-tag></div></template>
      <el-descriptions :column="4" border><el-descriptions-item label="生产批">{{ counts.lots }}</el-descriptions-item><el-descriptions-item label="任务">{{ counts.tasks }}</el-descriptions-item><el-descriptions-item label="依赖">{{ counts.dependencies }}</el-descriptions-item><el-descriptions-item label="物料需求">{{ counts.materialDemands }}</el-descriptions-item></el-descriptions>
      <el-table :data="expansion.tasks"><el-table-column prop="taskCode" label="稳定任务编码" min-width="220" /><el-table-column prop="taskName" label="任务" /><el-table-column prop="taskQty" label="数量" width="90" /><el-table-column prop="runSeconds" label="运行秒" width="100" /><el-table-column prop="status" label="状态" width="110" /></el-table>
      <h4>显式依赖</h4><el-table :data="expansion.dependencies"><el-table-column label="来源任务"><template #default="s">{{taskName(s.row.predecessorTaskId)}}</template></el-table-column><el-table-column label="目标任务"><template #default="s">{{taskName(s.row.successorTaskId)}}</template></el-table-column><el-table-column prop="dependencyType" label="语义" width="120" /><el-table-column prop="thresholdQty" label="门槛" width="90" /></el-table>
      <h4>生产批</h4><el-table :data="expansion.lots"><el-table-column prop="lotNo" label="批号"/><el-table-column label="产品行"><template #default="s">{{lineLabel(expansion?.order.lines.find(l=>l.id===s.row.orderLineId))}}</template></el-table-column><el-table-column prop="plannedQty" label="计划量"/><el-table-column prop="uomCode" label="单位"/></el-table><h4>物料需求与供给</h4><el-table :data="expansion.materialDemands"><el-table-column label="物料"><template #default="s">{{itemName(s.row.itemId)}}</template></el-table-column><el-table-column label="目标任务"><template #default="s">{{taskName(s.row.targetTaskId)}}</template></el-table-column><el-table-column label="来源任务"><template #default="s">{{s.row.sourceTaskId?taskName(s.row.sourceTaskId):'外部供给'}}</template></el-table-column><el-table-column prop="requiredQty" label="需用量"/><el-table-column prop="uomCode" label="单位"/></el-table>
    </el-card>

    <el-dialog v-model="orderDialog" :title="editing ? '编辑未展开草稿' : importMode ? '幂等导入订单' : '新增多产品订单'" width="min(1100px,96vw)"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/>
      <el-form label-width="90px"><el-row :gutter="12"><el-col :span="8"><el-form-item label="订单号"><el-input v-model="orderForm.orderNo" :disabled="!!editing" /></el-form-item></el-col><el-col :span="6"><el-form-item label="来源"><el-input v-model="orderForm.sourceSystem" :disabled="!!editing" /></el-form-item></el-col><el-col :span="7"><el-form-item label="外部 ID"><el-input v-model="orderForm.externalId" :disabled="!!editing" /></el-form-item></el-col><el-col :span="3"><el-form-item label="优先级"><el-input-number v-model="orderForm.priority" :min="1" :max="100" /></el-form-item></el-col></el-row><el-form-item label="客户"><el-input v-model="orderForm.customerName"/></el-form-item><el-form-item label="客户编码"><el-input v-model="orderForm.customerCode"/></el-form-item><el-form-item :label="`承诺时间（${site?.zoneId||'站点时区'}）`"><el-date-picker v-model="orderForm.promisedAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-form-item label="最早开始"><el-date-picker v-model="orderForm.earliestStartAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-form-item label="备注"><el-input v-model="orderForm.remark" maxlength="500"/></el-form-item></el-form>
      <div class="head"><h4>产品行</h4><el-button @click="addLine">添加产品行</el-button></div>
      <el-table :data="orderForm.lines"><el-table-column prop="lineNo" label="行号" width="70" /><el-table-column label="产品" min-width="160"><template #default="s"><el-select v-model="s.row.itemId" @change="lineItemChanged(s.row)"><el-option v-for="v in products" :key="v.id" :label="`${v.code} · ${v.name}`" :value="v.id" /></el-select></template></el-table-column><el-table-column label="路线" min-width="160"><template #default="s"><el-select v-model="s.row.routeVersionId" @change="clearRelations(s.row)"><el-option v-for="v in activeRoutes(s.row.itemId)" :key="v.id" :label="`${v.routeCode}/${v.versionNo}`" :value="v.id" /></el-select></template></el-table-column><el-table-column label="数量" width="130"><template #default="s"><el-input-number v-model="s.row.demandQty" :min="0.000001" /></template></el-table-column><el-table-column prop="uomCode" label="单位" width="75" /><el-table-column label="操作" width="80"><template #default="v"><el-button link @click="orderForm.lines.splice(v.$index,1)">移除</el-button></template></el-table-column><el-table-column label="行交期" min-width="210"><template #default="s"><el-date-picker v-model="s.row.promisedAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></template></el-table-column><el-table-column label="行最早开始" min-width="210"><template #default="s"><el-date-picker v-model="s.row.earliestStartAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></template></el-table-column><el-table-column label="关系" width="150"><template #default="s"><el-button link @click="openDependency(s.row)">依赖({{ s.row.dependencies.length }})</el-button><el-button link @click="openComponent(s.row)">物料({{ s.row.components.length }})</el-button></template></el-table-column></el-table>
<div v-for="line in orderForm.lines" :key="line.lineNo"><h4>{{lineLabel(line)}} · 显式关系</h4><div v-for="(d,i) in line.dependencies" :key="i">来源第{{d.predecessorLineNo}}行 {{d.predecessorNodeCode}} → {{d.successorNodeCode}} {{d.dependencyType}}<el-button link @click="line.dependencies.splice(i,1)">移除依赖</el-button></div><div v-for="(c,i) in line.components" :key="i">{{itemName(c.itemId)}} → {{c.targetNodeCode}} {{c.requiredQtyPerUnit}} {{c.uomCode}}<el-button link @click="line.components.splice(i,1)">移除物料需求</el-button></div></div>
      <template #footer><el-button @click="orderDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submitOrder">保存</el-button></template>
    </el-dialog>

<div v-if="orderDialog"><el-alert type="info" :closable="false" title="关系只使用已选择路线的业务节点；改变产品或路线会清空该行旧关系，请重新配置。"/></div>
    <el-dialog v-model="dependencyDialog" title="添加显式跨产品依赖" width="560px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-width="120px"><el-form-item label="来源产品行"><el-select v-model="dependencyForm.predecessorLineNo"><el-option v-for="v in orderForm.lines" :key="v.lineNo" :label="lineLabel(v)" :value="v.lineNo" /></el-select></el-form-item><el-form-item label="来源节点编码"><el-select v-model="dependencyForm.predecessorNodeCode" filterable><el-option v-for="n in nodes(orderForm.lines.find((l:any)=>l.lineNo===dependencyForm.predecessorLineNo))" :key="n.id" :label="`${n.nodeCode} · ${n.nodeName}`" :value="n.nodeCode"/></el-select></el-form-item><el-form-item label="目标节点编码"><el-select v-model="dependencyForm.successorNodeCode" filterable><el-option v-for="n in nodes(dependencyForm.targetLine)" :key="n.id" :label="`${n.nodeCode} · ${n.nodeName}`" :value="n.nodeCode"/></el-select></el-form-item><el-form-item label="依赖类型"><el-select v-model="dependencyForm.dependencyType"><el-option v-for="v in ['FINISH','QUANTITY','SAME_START']" :key="v" :value="v" /></el-select></el-form-item><el-form-item v-if="dependencyForm.dependencyType==='QUANTITY'" label="数量门槛"><el-input-number v-model="dependencyForm.thresholdQty" :min="0.000001" /></el-form-item></el-form><template #footer><el-button @click="dependencyDialog=false">取消</el-button><el-button type="primary" @click="addDependency">添加</el-button></template></el-dialog>
    <el-dialog v-model="componentDialog" title="添加组件/转移需求" width="600px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-width="120px"><el-form-item label="目标节点编码"><el-select v-model="componentForm.targetNodeCode" filterable><el-option v-for="n in nodes(componentForm.targetLine)" :key="n.id" :label="`${n.nodeCode} · ${n.nodeName}`" :value="n.nodeCode"/></el-select></el-form-item><el-form-item label="物料"><el-select v-model="componentForm.itemId" @change="componentItemChanged"><el-option v-for="v in items" :key="v.id" :label="`${v.code} · ${v.name}`" :value="v.id" /></el-select></el-form-item><el-form-item label="需求类型"><el-select v-model="componentForm.demandType"><el-option v-for="v in ['COMPONENT','TRANSFER','EXTERNAL']" :key="v" :value="v" /></el-select></el-form-item><el-form-item v-if="componentForm.demandType==='TRANSFER'" label="来源产品行"><el-select v-model="componentForm.sourceLineNo"><el-option v-for="v in orderForm.lines" :key="v.lineNo" :label="lineLabel(v)" :value="v.lineNo" /></el-select></el-form-item><el-form-item v-if="componentForm.demandType==='TRANSFER'" label="来源节点编码"><el-select v-model="componentForm.sourceNodeCode" filterable><el-option v-for="n in nodes(orderForm.lines.find((l:any)=>l.lineNo===componentForm.sourceLineNo))" :key="n.id" :label="`${n.nodeCode} · ${n.nodeName}`" :value="n.nodeCode"/></el-select></el-form-item><el-form-item label="单位用量"><el-input-number v-model="componentForm.requiredQtyPerUnit" :min="0.000001" /></el-form-item></el-form><template #footer><el-button @click="componentDialog=false">取消</el-button><el-button type="primary" @click="addComponent">添加</el-button></template></el-dialog>
    <el-dialog v-model="migrationDialog" title="未展开订单行路线迁移" width="620px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-width="120px"><el-form-item label="订单行"><el-select v-model="migrationForm.lineId"><el-option v-for="v in selected?.lines" :key="v.id" :label="`第 ${v.lineNo} 行 · ${itemName(v.itemId)}`" :value="v.id" /></el-select></el-form-item><el-form-item label="目标路线"><el-select v-model="migrationForm.targetRouteVersionId"><el-option v-for="v in migrationRoutes" :key="v.id" :label="`${v.routeCode}/${v.versionNo}`" :value="v.id" /></el-select></el-form-item></el-form><template #footer><el-button @click="migrationDialog=false">取消</el-button><el-button type="primary" @click="previewMigration">查看差异并确认</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { getRoute, updateDraftOrder, confirmRouteMigration, expandOrder, getExpansion, listItems, listOrders, listRoutes, previewRouteMigration, releaseOrder, saveOrder } from '@/api/aps/manufacturing'
import { useRoute } from 'vue-router'
import { getSiteContext, type ApsSiteContext } from '@/api/aps/context'
import { siteTime, siteTimeToUtc, operationError } from '@/components/aps/shared/site-time'
import type { ApsRouteGraph, ApsExpansion, ApsItem, ApsOrder, ApsOrderLine, ApsRouteVersion } from '@/types/aps/manufacturing'
import { addExplicitDependency, expansionCounts, normalizeOrderLines } from './order-model'

const pageError=ref(''),formError=ref(''),search=ref(''),saving=ref(false),editing=ref<ApsOrder>(),site=ref<ApsSiteContext>(),graphs=ref<Record<string,ApsRouteGraph>>({})
const route=useRoute();let selection=0
const items = ref<ApsItem[]>([]), routes = ref<ApsRouteVersion[]>([]), orders = ref<ApsOrder[]>([])
const selected = ref<ApsOrder>(), expansion = ref<ApsExpansion>()
const orderDialog = ref(false), dependencyDialog = ref(false), componentDialog = ref(false), migrationDialog = ref(false), importMode = ref(false)
const orderForm = reactive<any>({ orderNo: '', sourceSystem: 'LOCAL', externalId: '', priority: 50, lines: [] })
const dependencyForm = reactive<any>({ targetLine: undefined, predecessorLineNo: 1, predecessorNodeCode: '', successorNodeCode: '', dependencyType: 'FINISH', thresholdQty: undefined })
const componentForm = reactive<any>({ targetLine: undefined, targetNodeCode: '', itemId: '', demandType: 'COMPONENT', sourceLineNo: undefined, sourceNodeCode: '', requiredQtyPerUnit: 1, uomCode: 'PCS' })
const migrationForm = reactive<any>({ lineId: '', targetRouteVersionId: '' })
const products = computed(() => items.value.filter(value => value.type !== 'MATERIAL' && value.status === 'ACTIVE'))
const visibleOrders=computed(()=>orders.value.filter(o=>(o.orderNo+o.customerName).toLowerCase().includes(search.value.toLowerCase())))
const counts = computed(() => expansion.value ? expansionCounts(expansion.value) : { lots: 0, tasks: 0, dependencies: 0, materialDemands: 0 })
const migrationRoutes = computed(() => { const line = selected.value?.lines.find(value => value.id === migrationForm.lineId); return line ? activeRoutes(line.itemId).filter(value => value.id !== line.routeVersionId) : [] })

async function refresh(){[items.value,routes.value,orders.value,site.value]=await Promise.all([listItems(),listRoutes(),listOrders(),getSiteContext()]);const wanted=typeof route?.query.objectId==='string'?route.query.objectId:'';if(wanted){for(const o of orders.value){const x=await getExpansion(o.id);if(o.id===wanted||x.tasks.some(t=>t.id===wanted)||x.lots.some(l=>l.id===wanted)||x.materialDemands.some(d=>d.id===wanted)){selected.value=o;expansion.value=x;break}}}}
async function selectOrder(value?:ApsOrder){const token=++selection;selected.value=value;expansion.value=undefined;try{const result=value?await getExpansion(value.id):undefined;if(token===selection)expansion.value=result}catch(e){if(token===selection)pageError.value=operationError(e)}}
function itemName(id: string) { return items.value.find(value => value.id === id)?.name ?? id }
function routeName(id: string) { const value = routes.value.find(route => route.id === id); return value ? `${value.routeCode}/${value.versionNo}` : id }
function activeRoutes(itemId: string) { return routes.value.filter(value => value.itemId === itemId && value.status === 'ACTIVE') }
function openOrder(imported: boolean) { editing.value=undefined;formError.value=''; importMode.value = imported; Object.assign(orderForm, { orderNo: '', sourceSystem: imported ? 'ERP' : 'LOCAL', externalId: '', priority: 50, customerCode:'',customerName:'',promisedAt:'',earliestStartAt:'',remark:'',lines: [] }); addLine(); orderDialog.value = true }
function addLine() { orderForm.lines.push({ lineNo:Math.max(0,...orderForm.lines.map((l:any)=>l.lineNo))+1, itemId: '', routeVersionId: '', demandQty: 1, uomCode: 'PCS', components: [], dependencies: [] }) }
function lineItemChanged(line: any) { line.components=[];line.dependencies=[]; const item = items.value.find(value => value.id === line.itemId); line.uomCode = item?.baseUomCode ?? 'PCS'; line.routeVersionId = activeRoutes(line.itemId)[0]?.id ?? '';void loadGraphs() }
function openDependency(line: any) { Object.assign(dependencyForm, { targetLine: line, predecessorLineNo: orderForm.lines[0]?.lineNo ?? 1, predecessorNodeCode: '', successorNodeCode: '', dependencyType: 'FINISH', thresholdQty: undefined }); void loadGraphs(); dependencyDialog.value = true }
function addDependency() {if(!dependencyForm.predecessorNodeCode||!dependencyForm.successorNodeCode){formError.value='请选择来源和目标路线节点';return}if(dependencyForm.dependencyType==='QUANTITY'&&!(dependencyForm.thresholdQty>0)){formError.value='请填写正数数量门槛';return} addExplicitDependency(dependencyForm.targetLine, { predecessorLineNo: dependencyForm.predecessorLineNo, predecessorNodeCode: dependencyForm.predecessorNodeCode, successorNodeCode: dependencyForm.successorNodeCode, dependencyType: dependencyForm.dependencyType, thresholdQty: dependencyForm.dependencyType === 'QUANTITY' ? dependencyForm.thresholdQty : undefined, lagSeconds: 0, consumesOutput: false }); dependencyDialog.value = false }
function openComponent(line: any) { Object.assign(componentForm, { targetLine: line, targetNodeCode: '', itemId: '', demandType: 'COMPONENT', sourceLineNo: undefined, sourceNodeCode: '', requiredQtyPerUnit: 1, uomCode: 'PCS' }); void loadGraphs(); componentDialog.value = true }
function componentItemChanged() { componentForm.uomCode = items.value.find(value => value.id === componentForm.itemId)?.baseUomCode ?? 'PCS' }
function addComponent() {if(!componentForm.targetNodeCode||!componentForm.itemId||componentForm.demandType==='TRANSFER'&&(!componentForm.sourceLineNo||!componentForm.sourceNodeCode)){formError.value='请选择目标节点、物料及转移来源';return} componentForm.targetLine.components.push({ demandNo: componentForm.targetLine.components.length + 1, targetNodeCode: componentForm.targetNodeCode, itemId: componentForm.itemId, sourceLineNo: componentForm.demandType === 'TRANSFER' ? componentForm.sourceLineNo : undefined, sourceNodeCode: componentForm.demandType === 'TRANSFER' ? componentForm.sourceNodeCode : undefined, demandType: componentForm.demandType, requiredQtyPerUnit: componentForm.requiredQtyPerUnit, uomCode: componentForm.uomCode }); componentDialog.value = false }
async function expand(value:ApsOrder){if(saving.value)return;saving.value=true;pageError.value='';try{ expansion.value = await expandOrder(value.id); selected.value = value; ElMessage.success(expansion.value.reused ? '已复用原任务网络' : '任务网络已展开')}catch(e){pageError.value=operationError(e)}finally{saving.value=false}}
async function release(value:ApsOrder){if(saving.value)return;saving.value=true;pageError.value='';try{ await releaseOrder(value.id, value.rowVersion); await refresh(); ElMessage.success('订单结构已释放')}catch(e){pageError.value=operationError(e)}finally{saving.value=false}}
function openMigration() { const line = selected.value?.lines[0]; if (!line) return; migrationForm.lineId = line.id; migrationForm.targetRouteVersionId = ''; migrationDialog.value = true }
async function previewMigration() { if (!selected.value) return; const line = selected.value.lines.find(value => value.id === migrationForm.lineId); if (!line) return; const diff = await previewRouteMigration(line.id, migrationForm.targetRouteVersionId); const text = `新增节点：${diff.addedNodes.join(', ') || '无'}\n删除节点：${diff.removedNodes.join(', ') || '无'}\n变更工序：${diff.changedOperations.join(', ') || '无'}\n是否确认迁移？`; await ElMessageBox.confirm(text, '路线迁移差异', { type: 'warning' }); await confirmRouteMigration(line.id, { expectedCurrentRouteVersionId: line.routeVersionId, targetRouteVersionId: migrationForm.targetRouteVersionId, rowVersion: line.rowVersion, confirmed: true }); migrationDialog.value = false; await refresh(); ElMessage.success('未展开订单行已迁移路线') }
function nodes(line?:any){return line?graphs.value[line.routeVersionId]?.nodes||[]:[]}
function lineLabel(line?:any){return line?`第${line.lineNo}行 · ${itemName(line.itemId)}`:'未选择'}
function taskName(id:string){return expansion.value?.tasks.find(t=>t.id===id)?.taskName||'未知任务'}
function clearRelations(line:any){line.components=[];line.dependencies=[];void loadGraphs()}
async function loadGraphs(){try{const pairs=await Promise.all(orderForm.lines.filter((l:any)=>l.routeVersionId).map(async(l:any)=>[l.routeVersionId,await getRoute(l.routeVersionId)]));graphs.value=Object.fromEntries(pairs)}catch(e){formError.value=operationError(e)}}
async function editOrder(order:ApsOrder){try{await selectOrder(order);if(expansion.value?.tasks.length)throw new Error('订单已展开，结构已冻结；请使用路线迁移或新订单');editing.value=order;importMode.value=false;Object.assign(orderForm,JSON.parse(JSON.stringify(order)));if(!site.value)throw new Error('站点时区未就绪');for(const field of ['promisedAt','earliestStartAt'])orderForm[field]=siteTime(order[field as 'promisedAt'],site.value.zoneId);for(const line of orderForm.lines){line.promisedAt=siteTime(line.promisedAt,site.value.zoneId);line.earliestStartAt=siteTime(line.earliestStartAt,site.value.zoneId)}formError.value='';await loadGraphs();orderDialog.value=true}catch(e){pageError.value=operationError(e)}}
async function submitOrder(){if(saving.value)return;saving.value=true;formError.value='';try{if(!site.value)throw new Error('站点时区未就绪');if(!orderForm.orderNo.trim())throw new Error('订单号不能为空');const utc=(v:string)=>v?siteTimeToUtc(v,site.value!.zoneId):undefined;const lines=normalizeOrderLines(orderForm.lines).map(l=>({...l,promisedAt:utc(l.promisedAt as string),earliestStartAt:utc(l.earliestStartAt as string)}));const payload={...orderForm,promisedAt:utc(orderForm.promisedAt),earliestStartAt:utc(orderForm.earliestStartAt),externalId:orderForm.externalId||undefined,lines};const result=editing.value?await updateDraftOrder(editing.value.id,editing.value.rowVersion,payload):await saveOrder(payload,importMode.value);orderDialog.value=false;ElMessage.success('订单已保存');try{await refresh();await selectOrder(result)}catch(e){pageError.value='保存成功但回查失败：'+operationError(e)}}catch(e){formError.value=operationError(e)}finally{saving.value=false}}
onMounted(async()=>{try{await refresh()}catch(e){pageError.value=operationError(e)}})
</script>

<style scoped>.aps-orders{display:grid;gap:16px}.section-card{margin-top:16px}.head{display:flex;align-items:center;justify-content:space-between;gap:12px}</style>
